-- ============================================================================
-- Trivia Católica — Migración 011:
-- 1. Nueva categoría: Fe en la vida diaria (4 niveles, 20 situaciones cotidianas)
-- 2. Especial de Santos: San Aníbal María Di Francia (Nivel 6, 5 preguntas)
-- 3. Textos completos de Biblia y Catecismo (CIC) en reference_texts
-- 100% idempotente: se puede correr más de una vez sin duplicar.
-- ============================================================================

-- 1. Categoría nueva (sort_order = 0 para aparecer primero en el carrusel)
values (
  '11111111-1111-4111-8111-111111111109',
  'vida-diaria',
  'Fe en la vida diaria',
  'Adversidades, noviazgo, matrimonio, trabajo y decisiones de hoy con Jesús.',
  'sun-horizon',
  'cat-vd',
  0,
  false
)
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  icon = excluded.icon,
  color_token = excluded.color_token,
  sort_order = excluded.sort_order;

-- 2. 4 niveles de Fe en la vida diaria + Especial San Aníbal en Santos
on conflict (slug) do update set
  title = excluded.title,
  subtitle = excluded.subtitle,
  difficulty = excluded.difficulty,
  is_premium = excluded.is_premium;

-- 3. 25 preguntas nuevas (20 de Fe en la vida diaria + 5 Especial San Aníbal)
on conflict (id) do update set
  topic_id = excluded.topic_id,
  level_id = excluded.level_id,
  difficulty = excluded.difficulty,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_index = excluded.correct_index,
  explanation = excluded.explanation,
  source_ref = excluded.source_ref,
  is_active = true;

-- 4. Textos completos de referencia (Biblia + CIC) en reference_texts
on conflict (ref_key) do update set
  source_type = excluded.source_type,
  title = excluded.title,
  book_or_section = excluded.book_or_section,
  body = excluded.body;
