insert into public.levels (id, slug, topic_id, level_number, global_order, title, subtitle, difficulty, questions_per_round, is_premium)
values
  ('22222222-2222-4222-8222-222222222901', 'vida-diaria-adversidades-ansiedad', '11111111-1111-4111-8111-111111111109', 1, 33, 'Ante las adversidades y la ansiedad', 'Preocupaciones, cansancio, ofensas y confiar hoy', 1, 5, false),
  ('22222222-2222-4222-8222-222222222902', 'vida-diaria-noviazgo-amistad', '11111111-1111-4111-8111-111111111109', 2, 34, 'Noviazgo, amistad y amor real', 'Cuidado mutuo, sinceridad, límites y perdón', 1, 5, false),
  ('22222222-2222-4222-8222-222222222903', 'vida-diaria-matrimonio-familia', '11111111-1111-4111-8111-111111111109', 3, 35, 'Matrimonio y vida en familia', 'Diálogo en casa, paciencia, crianza y unidad', 2, 5, true),
  ('22222222-2222-4222-8222-222222222904', 'vida-diaria-trabajo-decisiones', '11111111-1111-4111-8111-111111111109', 4, 36, 'Trabajo, dinero y decisiones de hoy', 'Honestidad, descanso, envidia, chismes y generosidad', 2, 5, false),
  ('22222222-2222-4222-8222-222222222306', 'santos-san-anibal-maria-di-francia', '11111111-1111-4111-8111-111111111103', 6, 37, 'Especial: San Aníbal María Di Francia', 'Apóstol del Rogate, padre de los huérfanos y los pobres', 1, 5, false)
insert into public.questions (id, topic_id, level_id, difficulty, prompt, options, correct_index, explanation, source_ref, is_active)
values
  ('44444444-4444-4444-8444-444444449101', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222901', 1, 'Tenés la cabeza llena de preocupaciones por el mes que viene y no podés dormir. ¿Qué propone Jesús para bajar la ansiedad del día a día?', '["Vivir hoy confiando en Dios, porque a cada día le basta su propio afán","Dejar de planificar y no volver a trabajar","Ocultar lo que sentís para que nadie note tu cansancio","Resolver todo solo antes de pedir ayuda"]'::jsonb, 0, 'Jesús no pide irresponsabilidad, sino soltar la angustia paralizante: hacer lo que nos toca hoy y confiar el mañana al Padre.', 'Mt 6,34 · CIC 2633', true),
  ('44444444-4444-4444-8444-444444449102', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222901', 1, 'Sentís que la carga del trabajo, la casa y los problemas te superan por completo. ¿Qué invitación concreta hace Jesús a quienes están agotados?', '["Aumentar el esfuerzo hasta no sentir nada","Venir a Él con ese cansancio para encontrar descanso y alivio","Esperar a estar perfecto para acercarse a rezar","Alejarse de la familia hasta resolver todo"]'::jsonb, 1, 'En el Evangelio Jesús llama a los cansados y agobiados: la fe no es una carga extra, sino el lugar donde se recupera el aliento.', 'Mt 11,28-30 · CIC 2559', true),
  ('44444444-4444-4444-8444-444444449103', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222901', 1, 'Alguien cercano te hirió con un comentario injusto y te dan ganas de responderle el doble de fuerte. ¿Cuál es el camino que enseña Jesús?', '["Devolver el golpe rápido para marcar territorio","Cortar el trato y hablar mal de esa persona con otros","No devolver mal por mal y responder con serenidad y bien","Fingir que no dolió y guardar resentimiento en silencio"]'::jsonb, 2, 'Responder con calma y verdad rompe la cadena de agresión; perdonar no es justificar la ofensa, sino negarse a vivir atrapado en el rencor.', 'Rm 12,17-21 · CIC 2844', true),
  ('44444444-4444-4444-8444-444444449104', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222901', 2, 'Atravesás una mala racha personal y sentís que Dios está lejos o en silencio. ¿Qué escena del Evangelio recuerda que Jesús sigue en tu barca?', '["La multiplicación de los panes en la montaña","La entrada en Jerusalén con palmas","Las bodas de Caná","La tempestad calmada mientras los discípulos creían que Jesús dormía"]'::jsonb, 3, 'Aunque en medio de la tormenta parezca que Dios duerme, Él va en la misma barca y sostiene a quien le pide ayuda con sinceridad.', 'Mc 4,35-41 · CIC 2734', true),
  ('44444444-4444-4444-8444-444444449105', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222901', 2, 'Recibís una mala noticia que te desarma los planes. ¿Qué promete Jesús a sus amigos ante las dificultades del mundo?', '["Que nunca tendrán problemas ni enfermedades","Que tengan valor y paz, porque Él ha vencido al mundo","Que todo se arreglará automáticamente sin esfuerzo","Que el dolor significa que Dios está enojado"]'::jsonb, 1, 'Jesús es realista: no oculta que en la vida habrá pruebas, pero asegura su presencia y una paz más honda que las circunstancias.', 'Jn 16,33 · CIC 1820', true),
  ('44444444-4444-4444-8444-444444449201', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222902', 1, 'Estás conociendo a alguien en un noviazgo y te preguntás si es un amor sano. Según san Pablo, ¿cómo se reconoce el amor verdadero?', '["Es paciente, servicial, no es celoso ni busca solo su propio interés","Controla cada mensaje y cada salida de la otra persona","Se basa solo en emociones intensas sin compromiso","Evita hablar de límites para no incomodar"]'::jsonb, 0, 'El amor cristiano cuida la libertad y la dignidad del otro; los celos posesivos y el egoísmo no son señales de amor, sino de inseguridad.', '1 Co 13,4-7 · CIC 1822', true),
  ('44444444-4444-4444-8444-444444449202', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222902', 1, 'En una relación de noviazgo, ¿por qué la Iglesia valora el cuidado y el respeto mutuo en el afecto y el cuerpo?', '["Porque el cariño humano es algo negativo","Porque enseña a amar a la persona entera y no usarla para el propio placer","Para que los novios no se conozcan a fondo","Solo por una costumbre antigua sin sentido hoy"]'::jsonb, 1, 'La castidad en el noviazgo no es represión, sino aprendizaje del amor fiel: valorar a la otra persona como un don y nunca como un objeto.', '1 Ts 4,3-5 · CIC 2350', true),
  ('44444444-4444-4444-8444-444444449203', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222902', 1, 'Un amigo está tomando malas decisiones que lo lastiman y todos prefieren callar para no quedar mal. ¿Qué propone Jesús ante un hermano que se equivoca?', '["Exponerlo delante de todos en un grupo de chat","Ignorarlo para no meterse en problemas","Hablarle a solas con respeto y cariño para ayudarlo a reaccionar","Cortar la amistad sin explicarle nada"]'::jsonb, 2, 'La corrección fraterna que enseña Jesús busca siempre recuperar al amigo en privado, con humildad y sin humillarlo.', 'Mt 18,15 · CIC 1829', true),
  ('44444444-4444-4444-8444-444444449204', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222902', 2, '¿Cuál es la regla de oro que dejó Jesús para tratar a tu pareja, a tus amigos y a cualquier persona cada día?', '["Tratar a los demás según cómo te traten primero","Ayudar solo a quienes puedan devolverte el favor","Poner tus gustos por encima de todo","Hacer con los demás lo que querés que hagan con vos"]'::jsonb, 3, 'La regla de oro resume el Evangelio en lo cotidiano: ponerse en el lugar del otro antes de hablar, decidir o exigir.', 'Mt 7,12 · CIC 1789', true),
  ('44444444-4444-4444-8444-444444449205', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222902', 2, 'Un amigo te falló varias veces y ahora viene a pedirte perdón sinceramente. Cuando Pedro preguntó cuántas veces perdonar, ¿qué respondió Jesús?', '["Hasta tres veces como máximo","Setenta veces siete: tener un corazón siempre dispuesto a perdonar","Solo si nunca más vuelve a equivocarse","Una sola vez para que aprenda la lección"]'::jsonb, 1, '«Setenta veces siete» simboliza un perdón sin calculadora. Perdonar libera el corazón, aun cuando también sea sano poner límites claros.', 'Mt 18,21-22 · CIC 2840', true),
  ('44444444-4444-4444-8444-444444449301', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222903', 1, 'Hubo una discusión fuerte en pareja y el clima en casa quedó helado. ¿Qué consejo práctico de san Pablo ayuda a cuidar el matrimonio?', '["Que no se ponga el sol sobre tu enojo: buscar la paz antes de terminar el día","Dejar pasar semanas en silencio hasta olvidar el tema","Ganar la discusión recordando errores de años atrás","Contar la pelea a terceros antes de hablar con tu cónyuge"]'::jsonb, 0, 'Resolver el malentendido pronto —con un gesto de humildad o un «hablemos con calma»— evita que el orgullo construya muros en casa.', 'Ef 4,26-27 · CIC 2302', true),
  ('44444444-4444-4444-8444-444444449302', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222903', 2, 'En el matrimonio, las diferencias de carácter y los cansancios son inevitables. ¿Sobre qué imagen dice Jesús que se construye una casa que resiste las tormentas?', '["Sobre evitar cualquier problema económico","Sobre la roca de escuchar su Palabra y ponerla en práctica juntos","Sobre tener siempre la misma opinión en todo","Sobre vivir aislados del resto de la familia"]'::jsonb, 1, 'Todas las familias pasan lluvias y vientos; lo que sostiene la casa es edificar sobre la fidelidad, el diálogo y los valores del Evangelio.', 'Mt 7,24-25 · CIC 1644', true),
  ('44444444-4444-4444-8444-444444449303', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222903', 2, '¿Qué enseña la Escritura sobre la forma de educar y corregir a los hijos en la vida familiar?', '["No poner nunca límites para que no se enojen","Exigir perfección constante sin felicitar sus logros","Educarlos con amor, paciencia y firmeza, sin exasperarlos ni herirlos","Delegar toda la formación solo en la escuela"]'::jsonb, 2, 'Educar con cariño y límites claros da seguridad a los hijos; el Catecismo recuerda que el hogar es la primera escuela de amor y fe.', 'Ef 6,4 · CIC 2223', true),
  ('44444444-4444-4444-8444-444444449304', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222903', 2, 'En una cena familiar surge un tema tenso y todos hablan a la vez. ¿Qué actitud propone la carta de Santiago para conversar mejor?', '["Hablar más fuerte para imponer tu punto de vista","Irse de la mesa sin despedirse","Cambiar de tema con ironía","Ser pronto para escuchar, lento para hablar y lento para enojarse"]'::jsonb, 3, 'Escuchar de verdad antes de contestar baja la tensión en cualquier familia y demuestra respeto por quien tenemos enfrente.', 'St 1,19 · CIC 2219', true),
  ('44444444-4444-4444-8444-444444449305', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222903', 1, 'Al pensar en la unidad del matrimonio, ¿por qué la Iglesia llama a la familia cristiana «Iglesia doméstica»?', '["Porque reemplaza la Misa del domingo","Porque en el hogar se aprende a amar, perdonar, rezar y servirse mutuamente cada día","Porque solo pueden vivir en ella personas consagradas","Porque hay que hacer sermones largos en casa"]'::jsonb, 1, 'Dios habita en los gestos sencillos del hogar: compartir la mesa, pedir disculpas, cuidar a los mayores y rezar juntos en lo cotidiano.', 'Mt 19,6 · CIC 1656', true),
  ('44444444-4444-4444-8444-444444449401', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222904', 1, 'Te ofrecen hacer un «atajo» deshonesto en el trabajo o en un cobro donde nadie se daría cuenta. ¿Qué enseña Jesús sobre las cosas pequeñas?', '["Quien es fiel en lo poco también será fiel en lo mucho","Si el monto es pequeño no tiene importancia moral","La honestidad solo cuenta si alguien está mirando","En los negocios vale cualquier regla con tal de ganar"]'::jsonb, 0, 'La integridad se construye en las decisiones chicas que nadie ve: ser honesto en lo cotidiano trae paz de conciencia y confianza.', 'Lc 16,10 · CIC 2409', true),
  ('44444444-4444-4444-8444-444444449402', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222904', 1, 'Ves en redes sociales la vida y los logros de otros y empezás a sentir envidia o que lo tuyo no vale nada. ¿Qué advierte Jesús sobre dónde poner el corazón?', '["Que el valor de una persona depende de cuántos bienes acumula","Que la vida de una persona no depende de la abundancia de sus bienes","Que está mal disfrutar del fruto del propio trabajo","Que hay que compararse siempre para superarse"]'::jsonb, 1, 'Compararnos todo el tiempo roba la alegría. Jesús recuerda que nuestra dignidad no se mide por lo que mostramos o tenemos, sino por cómo amamos.', 'Lc 12,15 · CIC 2539', true),
  ('44444444-4444-4444-8444-444444449403', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222904', 2, 'Trabajás de lunes a lunes sin parar, con el celular encendido todo el domingo. ¿Por qué Dios nos regala el descanso dominical?', '["Para prohibir toda actividad recreativa en familia","Porque trabajar es algo malo","Porque el ser humano no es una máquina: necesita descansar, celebrar y reencontrarse con Dios y los suyos","Solo para quienes no tienen responsabilidades"]'::jsonb, 2, 'El domingo recuerda que somos más que lo que producimos: un día para frenar, agradecer, compartir la mesa y renovar el alma.', 'Mc 2,27 · CIC 2184', true),
  ('44444444-4444-4444-8444-444444449404', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222904', 1, 'En una charla con compañeros empiezan a circular chismes sobre alguien que no está presente. ¿Cuál es la actitud cristiana más coherente?', '["Sumarse al comentario para encajar en el grupo","Escuchar todo y después contárselo a otros en privado","Grabar la conversación para tener pruebas","No alimentar el chisme y cuidar la buena fama de quien no puede defenderse"]'::jsonb, 3, 'El Catecismo señala que la maledicencia y la calumnia hieren la dignidad del prójimo; cuidar las palabras construye ambientes sanos.', 'Ef 4,29 · CIC 2477', true),
  ('44444444-4444-4444-8444-444444449405', '11111111-1111-4111-8111-111111111109', '22222222-2222-4222-8222-222222222904', 2, 'Cuando ayudás a alguien que lo necesita, ¿qué detalle pide Jesús respecto a presumir de nuestras buenas obras?', '["Publicarlo siempre para recibir aplausos","Ayudar con sencillez y sin buscar fama, porque el Padre ve en lo secreto","Hacerlo solo si te agradecen en público","Esperar a tener mucho dinero sobrante para ayudar"]'::jsonb, 1, 'La generosidad auténtica busca el bien del otro y no el aplauso propio; «hay más alegría en dar que en recibir».', 'Mt 6,3-4 · CIC 2447', true),
  ('44444444-4444-4444-8444-444444443601', '11111111-1111-4111-8111-111111111103', '22222222-2222-4222-8222-222222222306', 1, '¿Qué mandato de Jesús descubrió san Aníbal María Di Francia como el corazón de su misión, resumido en la palabra latina «Rogate»?', '["«Rueguen al Dueño de la mies que envíe obreros a su mies»","«Vayan y construyan templos de piedra»","«Guarden silencio y no prediquen en las ciudades»","«Escriban leyes para gobernar las naciones»"]'::jsonb, 0, 'San Aníbal entendió el «Rogate» (rueguen) como un verdadero mandamiento de Jesús: rezar sin descanso por buenas y santas vocaciones para la Iglesia.', 'Mt 9,37-38 · CIC 2635', true),
  ('44444444-4444-4444-8444-444444443602', '11111111-1111-4111-8111-111111111103', '22222222-2222-4222-8222-222222222306', 1, '¿En qué ciudad italiana nació san Aníbal María Di Francia y comenzó su entrega a los pobres y huérfanos en el humilde barrio de Avignone?', '["Venecia","Mesina, en Sicilia","Milán","Florencia"]'::jsonb, 1, 'Nacido en Mesina en 1851 en una familia noble, san Aníbal dejó toda comodidad para entrar al barrio más pobre, Avignone, y servir a Cristo en los más abandonados.', 'Mt 25,40 · CIC 2443', true),
  ('44444444-4444-4444-8444-444444443603', '11111111-1111-4111-8111-111111111103', '22222222-2222-4222-8222-222222222306', 1, '¿Qué dos congregaciones religiosas fundó san Aníbal María Di Francia para vivir la oración por las vocaciones y la caridad?', '["Salesianos e Hijas de María Auxiliadora","Franciscanos y Clarisas","Padres Rogacionistas del Corazón de Jesús e Hijas del Divino Celo","Jesuitas y Carmelitas Descalzas"]'::jsonb, 2, 'Fundó a las Hijas del Divino Celo (1887) y a los Padres Rogacionistas del Corazón de Jesús (1897), cuyo cuarto voto es precisamente vivir y difundir el «Rogate».', 'Lc 10,2 · CIC 926', true),
  ('44444444-4444-4444-8444-444444443604', '11111111-1111-4111-8111-111111111103', '22222222-2222-4222-8222-222222222306', 1, '¿Con qué título cariñoso recordaba el pueblo a san Aníbal por abrir orfanatos y escuelas para los niños más necesitados?', '["Doctor de los concilios","Misionero de los mares","Constructor de catedrales","Padre de los huérfanos y de los pobres"]'::jsonb, 3, 'A los niños y niñas huérfanos los llamaba sus «pequeños reyes», asegurándoles techo, educación, oficio y una familia donde sentirse amados por Dios.', 'St 1,27 · CIC 2447', true),
  ('44444444-4444-4444-8444-444444443605', '11111111-1111-4111-8111-111111111103', '22222222-2222-4222-8222-222222222306', 2, '¿Qué Papa canonizó a san Aníbal María Di Francia el 16 de mayo de 2004, llamándolo precursor de la pastoral vocacional (fiesta el 1 de junio)?', '["San Pío X","San Juan Pablo II","San Pablo VI","San Juan XXIII"]'::jsonb, 1, 'San Juan Pablo II lo proclamó santo en la Plaza de San Pedro el 16 de mayo de 2004, reconociendo su carisma profético de oración por las vocaciones.', 'Jn 15,16 · CIC 828', true)
insert into public.reference_texts (ref_key, source_type, title, book_or_section, body)
values
  ('Mt 6,34', 'biblia', 'Mateo 6, 34', 'Nuevo Testamento · Sermón de la Montaña', '«No se inquieten por el día de mañana; el mañana se preocupará por sí mismo. A cada día le basta su propia aflicción.»'),
  ('CIC 2633', 'cic', 'Catecismo de la Iglesia Católica · N.° 2633', 'Cuarta Parte · La oración de petición y confianza', 'Cuando se participa así en el amor salvador de Dios, se comprende que toda necesidad puede convertirse en objeto de petición. Cristo, que ha asumido todo para rescatar todo, es glorificado por las peticiones que ofrecemos al Padre en su Nombre.'),
  ('Mt 11,28-30', 'biblia', 'Mateo 11, 28-30', 'Nuevo Testamento · Evangelio según san Mateo', '«Vengan a mí todos los que están afligidos y agobiados, y yo los aliviaré. Carguen sobre ustedes mi yugo y aprendan de mí, porque soy paciente y humilde de corazón, y así encontrarán alivio. Porque mi yugo es suave y mi carga liviana.»'),
  ('CIC 2559', 'cic', 'Catecismo de la Iglesia Católica · N.° 2559', 'Cuarta Parte · La oración como don y encuentro', '«La oración es la elevación del alma a Dios o la petición a Dios de bienes convenientes» (san Juan Damasceno). La humildad es la disposición necesaria para recibir gratuitamente el don de la oración.'),
  ('Rm 12,17-21', 'biblia', 'Romanos 12, 17-21', 'Nuevo Testamento · Carta a los Romanos', '«No devuelvan a nadie mal por mal... En lo posible, y en cuanto dependa de ustedes, vivan en paz con todos. No te dejes vencer por el mal; por el contrario, vence al mal haciendo el bien.»'),
  ('CIC 2844', 'cic', 'Catecismo de la Iglesia Católica · N.° 2844', 'Cuarta Parte · El perdón cristiano frente a la herida', 'La oración cristiana llega hasta el perdón de los enemigos. Transfigura al discípulo configurándolo con su Maestro. El perdón es cumbre de la oración cristiana y solo puede ser acogido por un corazón acorde con la compasión divina.'),
  ('Mc 4,35-41', 'biblia', 'Marcos 4, 35-41 (La tempestad calmada)', 'Nuevo Testamento · Milagros de Jesús', '«Jesús se despertó, increpó al viento y dijo al mar: "¡Silencio, cálmate!" El viento se aplacó y sobrevino una gran calma. Después les dijo: "¿Por qué tienen miedo? ¿Todavía no tienen fe?"»'),
  ('CIC 2734', 'cic', 'Catecismo de la Iglesia Católica · N.° 2734', 'Cuarta Parte · Confianza filial en la prueba', 'La confianza filial se pone a prueba cuando pensamos que no somos escuchados siempre. El Evangelio nos invita a preguntarnos si nuestra oración busca la voluntad del Padre, quien siempre nos da el Espíritu Santo.'),
  ('Jn 16,33', 'biblia', 'Juan 16, 33', 'Nuevo Testamento · Discurso de despedida', '«Les he dicho estas cosas para que encuentren la paz en mí. En el mundo tendrán que sufrir; pero tengan valor: yo he vencido al mundo.»'),
  ('CIC 1820', 'cic', 'Catecismo de la Iglesia Católica · N.° 1820', 'Tercera Parte · La virtud de la esperanza', 'La esperanza cristiana se despliega desde el comienzo de la predicación de Jesús en la proclamación de las bienaventuranzas. Es el arma que nos protege en el combate de la salvación y nos sostiene en las pruebas.'),
  ('1 Co 13,4-7', 'biblia', '1 Corintios 13, 4-7', 'Nuevo Testamento · Himno a la caridad', '«El amor es paciente, es servicial; el amor no es envidioso, no hace alarde, no se envanece, no procede con bajeza, no busca su propio interés, no se irrita, no tiene en cuenta el mal recibido, no se alegra de la injusticia, sino que se regocija con la verdad. Todo lo disculpa, todo lo cree, todo lo espera, todo lo soporta.»'),
  ('CIC 1822', 'cic', 'Catecismo de la Iglesia Católica · N.° 1822', 'Tercera Parte · La virtud de la caridad', 'La caridad es la virtud teologal por la cual amamos a Dios sobre todas las cosas por Él mismo y a nuestro prójimo como a nosotros mismos por amor de Dios.'),
  ('1 Ts 4,3-5', 'biblia', '1 Tesalonicenses 4, 3-5', 'Nuevo Testamento · Primera Carta a los Tesalonicenses', '«Lo que Dios quiere es que ustedes sean santos: que se aparten de la impureza, y que cada uno sepa tratar su cuerpo con santidad y respeto, sin dejarse llevar por la pasión desordenada.»'),
  ('CIC 2350', 'cic', 'Catecismo de la Iglesia Católica · N.° 2350', 'Tercera Parte · El noviazgo y el respeto mutuo', 'Los novios están llamados a vivir la castidad en la continencia. En esta prueba han de ver un descubrimiento del respeto mutuo, un aprendizaje de la fidelidad y de la esperanza de recibirse el uno y el otro de Dios.'),
  ('Mt 18,15', 'biblia', 'Mateo 18, 15', 'Nuevo Testamento · Corrección fraterna', '«Si tu hermano peca contra ti, ve y corrígelo en privado, a solas entre los dos. Si te escucha, habrás ganado a tu hermano.»'),
  ('CIC 1829', 'cic', 'Catecismo de la Iglesia Católica · N.° 1829', 'Tercera Parte · Los frutos de la caridad', 'La caridad tiene por frutos el gozo, la paz y la misericordia. Exige la práctica del bien y la corrección fraterna; es benevolencia; suscita la reciprocidad; es siempre desinteresada y generosa; es amistad y comunión.'),
  ('Mt 7,12', 'biblia', 'Mateo 7, 12', 'Nuevo Testamento · La regla de oro', '«Todo lo que deseen que los demás hagan por ustedes, háganlo por ellos: en esto consiste la Ley y los Profetas.»'),
  ('CIC 1789', 'cic', 'Catecismo de la Iglesia Católica · N.° 1789', 'Tercera Parte · La regla de oro en la conciencia moral', 'Algunas reglas se aplican en todos los casos: nunca está permitido hacer el mal para obtener un bien; la «regla de oro»: «Todo cuanto queráis que os hagan los hombres, hacédselo también vosotros a ellos»; la caridad pasa siempre por el respeto del prójimo y de su conciencia.'),
  ('Mt 18,21-22', 'biblia', 'Mateo 18, 21-22', 'Nuevo Testamento · El perdón sin límites', '«Entonces se adelantó Pedro y le dijo: "Señor, ¿cuántas veces tendré que perdonar a mi hermano las ofensas que me haga? ¿Hasta siete veces?" Jesús le respondió: "No te digo hasta siete veces, sino hasta setenta veces siete."»'),
  ('CIC 2840', 'cic', 'Catecismo de la Iglesia Católica · N.° 2840', 'Cuarta Parte · Perdonar de corazón', 'Esta corriente de misericordia no puede penetrar en nuestro corazón mientras no hayamos perdonado a los que nos han ofendido. El amor, como el Cuerpo de Cristo, es indivisible: no podemos amar a Dios a quien no vemos, si no amamos al hermano y a la hermana a quienes vemos.'),
  ('Ef 4,26-27', 'biblia', 'Efesios 4, 26-27', 'Nuevo Testamento · Carta a los Efesios', '«Si se enojan, no se dejen arrastrar al pecado ni permitan que la noche los sorprenda enojados, dejando así lugar al demonio.»'),
  ('CIC 2302', 'cic', 'Catecismo de la Iglesia Católica · N.° 2302', 'Tercera Parte · Dominar la ira y buscar la paz', 'Recordando el precepto «no matarás», nuestro Señor pide la paz del corazón y denuncia la inmoralidad de la cólera homicida y del odio. La ira es un deseo de venganza que destruye la comunión.'),
  ('Mt 7,24-25', 'biblia', 'Mateo 7, 24-25', 'Nuevo Testamento · La casa sobre la roca', '«Así, todo el que escucha las palabras que acabo de decir y las pone en práctica, puede compararse a un hombre sensato que edificó su casa sobre roca. Cayeron las lluvias, se precipitaron los torrentes, soplaron los vientos y sacudieron la casa; pero esta no se derrumbó porque estaba construida sobre roca.»'),
  ('CIC 1644', 'cic', 'Catecismo de la Iglesia Católica · N.° 1644', 'Segunda Parte · Unidad e indisolubilidad del Matrimonio', 'El amor de los esposos exige, por su misma naturaleza, la unidad y la indisolubilidad de la comunidad de personas que abarca toda la vida de los esposos: «De manera que ya no son dos, sino una sola carne».'),
  ('Ef 6,4', 'biblia', 'Efesios 6, 4', 'Nuevo Testamento · Vida familiar', '«Y ustedes, padres, no irriten a sus hijos; al contrario, edúquenlos, corrigiéndolos e instruyéndolos según el Señor.»'),
  ('CIC 2223', 'cic', 'Catecismo de la Iglesia Católica · N.° 2223', 'Tercera Parte · Misión educativa de los padres', 'Los padres son los primeros responsables de la educación de sus hijos. Testimonian esta responsabilidad ante todo por la creación de un hogar, donde la ternura, el perdón, el respeto, la fidelidad y el servicio desinteresado son norma.'),
  ('St 1,19', 'biblia', 'Santiago 1, 19', 'Nuevo Testamento · Carta de Santiago', '«Tengan bien presente, hermanos muy queridos, que debemos estar siempre dispuestos a escuchar y ser lentos para hablar y para enojarnos.»'),
  ('CIC 2219', 'cic', 'Catecismo de la Iglesia Católica · N.° 2219', 'Tercera Parte · Respeto y armonía en la familia', 'El respeto filial favorece la armonía de toda la vida familiar; atañe también a las relaciones entre hermanos y hermanas. El respeto a los padres irradia en todo el ambiente familiar.'),
  ('Mt 19,6', 'biblia', 'Mateo 19, 6', 'Nuevo Testamento · Unidad del Matrimonio', '«De manera que ya no son dos, sino una sola carne. Que el hombre no separe lo que Dios ha unido.»'),
  ('CIC 1656', 'cic', 'Catecismo de la Iglesia Católica · N.° 1656', 'Segunda Parte · La Iglesia doméstica', 'En nuestros días, en un mundo frecuentemente extraño e incluso hostil a la fe, las familias creyentes tienen una importancia primordial en cuanto faros de una fe viva e irradiadora. Por eso el Concilio Vaticano II llama a la familia «Iglesia doméstica».'),
  ('Lc 16,10', 'biblia', 'Lucas 16, 10', 'Nuevo Testamento · Fidelidad en lo pequeño', '«El que es fiel en lo poco, también es fiel en lo mucho, y el que es deshonesto en lo poco, también es deshonesto en lo mucho.»'),
  ('CIC 2409', 'cic', 'Catecismo de la Iglesia Católica · N.° 2409', 'Tercera Parte · Honestidad en el trabajo y los bienes', 'Toda forma de tomar o retener injustamente el bien ajeno, aunque no contradiga las disposiciones de la ley civil, es contraria al séptimo mandamiento: así, retener deliberadamente bienes prestados u objetos perdidos, defraudar en el ejercicio del comercio o realizar trabajos mal hechos.'),
  ('Lc 12,15', 'biblia', 'Lucas 12, 15', 'Nuevo Testamento · Evangelio según san Lucas', '«Cuídense de toda avaricia, porque aun en medio de la abundancia, la vida de una persona no está asegurada por sus riquezas.»'),
  ('CIC 2539', 'cic', 'Catecismo de la Iglesia Católica · N.° 2539', 'Tercera Parte · Superar la envidia', 'La envidia es un pecado capital. Designa la tristeza experimentada ante el bien del prójimo y el deseo desordenado de apropiárselo. El bautizado lucha contra la envidia mediante la benevolencia, la humildad y el abandono en la providencia de Dios.'),
  ('Mc 2,27', 'biblia', 'Marcos 2, 27', 'Nuevo Testamento · El día de descanso', '«Y les dijo: "El sábado fue hecho para el hombre, y no el hombre para el sábado."»'),
  ('CIC 2184', 'cic', 'Catecismo de la Iglesia Católica · N.° 2184', 'Tercera Parte · El descanso dominical', 'Así como Dios «cesó el día séptimo de toda la tarea que había hecho», así también la vida humana está ordenada según un ritmo de trabajo y de descanso. La institución del día del Señor contribuye a que todos disfruten del tiempo de descanso y de solaz suficiente para cultivar la vida familiar, cultural, social y religiosa.'),
  ('Ef 4,29', 'biblia', 'Efesios 4, 29', 'Nuevo Testamento · Cuidar las palabras', '«No salga de sus labios ninguna palabra mala; digan únicamente lo que sirve para edificar según la necesidad y haga bien a quienes los escuchan.»'),
  ('CIC 2477', 'cic', 'Catecismo de la Iglesia Católica · N.° 2477', 'Tercera Parte · Respeto a la buena fama', 'El respeto de la reputación de las personas prohíbe toda actitud y toda palabra susceptibles de causarles un daño injusto. Se hace culpable de juicio temerario, de maledicencia o de calumnia quien daña la fama de otro.'),
  ('Mt 6,3-4', 'biblia', 'Mateo 6, 3-4', 'Nuevo Testamento · Generosidad sencilla', '«Cuando des limosna, que tu mano izquierda ignore lo que hace la derecha, para que tu limosna quede en secreto; y tu Padre, que ve en lo secreto, te recompensará.»'),
  ('CIC 2447', 'cic', 'Catecismo de la Iglesia Católica · N.° 2447', 'Tercera Parte · Las obras de misericordia', 'Las obras de misericordia son las acciones caritativas mediante las cuales ayudamos a nuestro prójimo en sus necesidades corporales y espirituales. La limosna hecha a los pobres es uno de los principales testimonios de la caridad fraterna.'),
  ('Mt 9,37-38', 'biblia', 'Mateo 9, 37-38', 'Nuevo Testamento · El mandato del Rogate', '«Entonces dijo a sus discípulos: "La cosecha es abundante, pero los trabajadores son pocos. Rueguen al dueño de los sembrados que envíe trabajadores para su cosecha."»'),
  ('CIC 2635', 'cic', 'Catecismo de la Iglesia Católica · N.° 2635', 'Cuarta Parte · La oración de intercesión', 'Interceder, pedir en favor de otro, es, desde Abraham, lo propio de un corazón conforme a la misericordia de Dios. En el tiempo de la Iglesia, la intercesión cristiana participa de la de Cristo y no conoce fronteras.'),
  ('Mt 25,40', 'biblia', 'Mateo 25, 40', 'Nuevo Testamento · El servicio a los pequeños', '«Les aseguro que cada vez que lo hicieron con el más pequeño de mis hermanos, lo hicieron conmigo.»'),
  ('CIC 2443', 'cic', 'Catecismo de la Iglesia Católica · N.° 2443', 'Tercera Parte · Amor preferencial por los pobres', 'Dios bendice a los que ayudan a los pobres y reprueba a los que se niegan a hacerlo. Jesús reconocerá a sus elegidos en lo que hayan hecho por los pobres.'),
  ('Lc 10,2', 'biblia', 'Lucas 10, 2', 'Nuevo Testamento · Oración por las vocaciones', '«Les decía: "La cosecha es abundante, pero los trabajadores son pocos. Rueguen al dueño de los sembrados que envíe trabajadores para su cosecha."»'),
  ('CIC 926', 'cic', 'Catecismo de la Iglesia Católica · N.° 926', 'Primera Parte · La vida religiosa en la Iglesia', 'La vida religiosa nace del misterio de la Iglesia. Es un don que la Iglesia recibe de su Señor y que ofrece con su gracia como un estado de vida estable para el servicio de Dios y de los hermanos.'),
  ('St 1,27', 'biblia', 'Santiago 1, 27', 'Nuevo Testamento · Caridad hacia los huérfanos', '«La religión pura e intachable ante Dios Padre consiste en visitar a los huérfanos y a las viudas en sus tribulaciones y en guardarse incontaminado del mundo.»'),
  ('Jn 15,16', 'biblia', 'Juan 15, 16', 'Nuevo Testamento · Llamado y vocación', '«No son ustedes los que me eligieron a mí, sino yo el que los elegí a ustedes, y los destiné para que vayan y den fruto, y ese fruto sea duradero.»'),
  ('CIC 828', 'cic', 'Catecismo de la Iglesia Católica · N.° 828', 'Primera Parte · Los santos, modelos e intercesores', 'Al canonizar a ciertos fieles, la Iglesia reconoce el poder del Espíritu de santidad y sostiene la esperanza de los creyentes proponiéndolos como modelos e intercesores.')
